def simulate():
    prod_node = node_by_title(doc, 'Plant 2103, Period 10: Products')
    prod_rows = table_rows(prod_node)
    products_data = {}
    for i, row in prod_rows:
        p = row['product']
        products_data[p] = {
            'weight': float(row['kg per unit']),
            'stock': int(row['opening stock'])
        }

    ledger_node = node_by_title(doc, 'Plant 2103, Period 10: Daily ledger')
    ledger_rows = table_rows(ledger_node)

    daily_data = {}
    all_days_set = set()
    for i, row in ledger_rows:
        day = int(row['day'])
        p = row['product']
        all_days_set.add(day)
        if day not in daily_data:
            daily_data[day] = {}
        daily_data[day][p] = {
            'produced': int(row['produced']),
            'ordered': int(row['ordered'])
        }

    all_days = sorted(list(all_days_set))

    order_queue = [] 
    order_counter = 0

    results = {
        'sos131_full': False,
        'pov134_full': False,
        'sos131_backordered': False,
        'popb_out_of_stock': False
    }

    for day in all_days:
        capacity = 407700 if day < 130 else 326160

        for p in products_data:
            if day in daily_data and p in daily_data[day]:
                products_data[p]['stock'] += daily_data[day][p]['produced']

        if day in daily_data:
            for p, data in daily_data[day].items():
                qty = data['ordered']
                if qty > 0:
                    order_queue.append([p, qty, day, order_counter, qty])
                    order_counter += 1

        order_queue.sort(key=lambda x: (x[2], x[1], x[0]))

        current_capacity = capacity
        new_queue = []

        for order in order_queue:
            p, rem_qty, day_placed, oid, orig_qty = order
            weight = products_data[p]['weight']

            max_by_stock = products_data[p]['stock']
            max_by_cap = int(current_capacity // weight)

            shipped = min(rem_qty, max_by_stock, max_by_cap)

            products_data[p]['stock'] -= shipped
            current_capacity -= shipped * weight

            remaining = rem_qty - shipped

            # Fixed tracking: must ship in full ON THE DAY it was placed
            if day == 131 and p == 'SOS001L12P' and day_placed == 131 and shipped == orig_qty:
                results['sos131_full'] = True
            if day == 134 and p == 'POV001L24P' and day_placed == 134 and shipped == orig_qty:
                results['pov134_full'] = True

            if remaining > 0:
                new_queue.append([p, remaining, day_placed, oid, orig_qty])

        order_queue = new_queue

        if day == 131:
            sos_backordered = sum(rem for p, rem, dp, oid, oq in order_queue if p == 'SOS001L12P')
            if sos_backordered > 0:
                results['sos131_backordered'] = True

        if 130 <= day <= 140:
            popb_stock = products_data['POP001L12P-B']['stock']
            popb_backordered = sum(rem for p, rem, dp, oid, oq in order_queue if p == 'POP001L12P-B')
            if popb_stock == 0 and popb_backordered > 0:
                results['popb_out_of_stock'] = True

    return results

